// The Oak welcome photo for /start — embedded as base64 because the
// serverless runtime has no filesystem and tgcloud.jsonc has no static
// block to host it (port of bot.py _welcome_photo_path -> send_photo_bytes).
// Source: help/assets/oak-welcome.jpg — the original /start image that
// commit 32ad11a removed from the Python bot; serverless never had it.
// Pure module (no sdk): tools/test_pure.mjs decodes this and byte-compares
// it against the source file on disk.

const B64 = '';

const B64_ALPHABET =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** Standard base64 -> bytes (the isolate has no atob). Whitespace and
 *  padding are tolerated; invalid characters are skipped. */
export function decodeBase64(str) {
  const lut = new Uint8Array(128);
  for (let i = 0; i < B64_ALPHABET.length; i++) lut[B64_ALPHABET.charCodeAt(i)] = i;
  const s = String(str || '').replace(/[^A-Za-z0-9+/]/g, '').replace(/=+$/, '');
  const out = new Uint8Array(Math.floor((s.length * 3) / 4));
  let acc = 0;
  let bits = 0;
  let n = 0;
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    const v = code < 128 ? lut[code] : -1;
    if (v < 0) continue;
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[n++] = (acc >> bits) & 0xff;
      acc &= (1 << bits) - 1;
    }
  }
  return out.subarray(0, n);
}

let cached = null;

/** JPEG bytes of the Oak welcome photo (decoded once per isolate). */
export function welcomeBytes() {
  if (!cached) cached = decodeBase64(B64);
  return cached;
}

/** Upload filename + content type (port of send_photo_bytes args). */
export const WELCOME_FILENAME = 'welcome.jpg';
export const WELCOME_MIME = 'image/jpeg';

/** JPEG SOI marker check (FF D8 FF). */
export function isJpeg(bytes) {
  return Boolean(bytes && bytes.length > 3
    && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff);
}
